q.append({"unit_id": "pharm-i-unit-3", "question_text": "Filter aids such as kieselguhr are added during filtration to:", "options": ["Form a porous layer on the filter medium that prevents clogging", "Dissolve the solid particles completely", "Increase the temperature of the slurry", "Colour the filtrate uniformly"], "correct_index": 0, "explanation": "Filter aids deposit a porous cake on the medium, trapping slimy solids on its surface so the filter does not clog and the filtrate stays clear.", "difficulty": "medium", "tags": ["filtration", "filter aids"]})
