q.append({"unit_id": "pharm-i-unit-3", "question_text": "A vacuum dryer is preferred for drying materials that are:", "options": ["Heat-sensitive and liable to decompose at high temperature", "Hard crystalline ores that need strong heat", "Highly radioactive waste products", "Completely dry and moisture-free already"], "correct_index": 0, "explanation": "Reducing pressure lowers the boiling point of the solvent, so moisture is removed at lower temperature, protecting thermolabile products.", "difficulty": "medium", "tags": ["drying", "vacuum dryer"]})
q.append({"unit_id": "pharm-i-unit-3", "question_text": "A drum (roller) dryer is best suited for drying:", "options": ["Solutions or slurries into thin flakes or sheets", "Bulky fibrous plant materials", "Large batches of tablets", "Gases by chemical absorption"], "correct_index": 0, "explanation": "In drum drying, liquid or slurry is spread as a thin film on heated rotating drums, evaporating rapidly and scraping off as dry flakes.", "difficulty": "medium", "tags": ["drying", "drum dryer"]})
q.append({"unit_id": "pharm-i-unit-3", "question_text": "During the constant-rate period of drying, the moisture being removed is mainly:", "options": ["Unbound surface moisture that behaves like free water", "Chemically bound water inside the crystal lattice", "Water of crystallisation of the salt", "Moisture held only at very high humidity"], "correct_index": 0, "explanation": "In the constant-rate phase, unbound surface moisture evaporates at a steady rate controlled by external conditions; the falling-rate phase removes bound moisture by diffusion.", "difficulty": "hard", "tags": ["drying", "drying curve"]})
q.append({"unit_id": "pharm-i-unit-3", "question_text": "A hygroscopic material is one that:", "options": ["Readily absorbs moisture from the surrounding air", "Loses all moisture even in a sealed container", "Never contains any water of crystallisation", "Repels water completely from its surface"], "correct_index": 0, "explanation": "Hygroscopic substances take up atmospheric moisture, so they must be stored in airtight containers, often with a desiccant.", "difficulty": "easy", "tags": ["drying", "hygroscopicity"]})
q.append({"unit_id": "pharm-i-unit-3", "question_text": "A ball mill must be run below the critical speed because at or above that speed the:", "options": ["Balls are carried round by centrifugal force and no grinding occurs", "Balls melt due to frictional heat", "Mill shell cracks from the impact", "Powder becomes sterile automatically"], "correct_index": 0, "explanation": "Above critical speed, centrifugal force holds the balls against the shell so they cease cascading and impacting, and grinding stops.", "difficulty": "hard", "tags": ["size reduction", "ball mill"]})

# ===== UNIT 4: EVAPORATION AND HEAT TRANSFER (15 new) =====
q.append({"unit_id": "pharm-i-unit-4", "question_text": "Multiple-effect evaporators are employed mainly to:", "options": ["Economise steam by reusing vapour from one effect to heat the next", "Evaporate liquids without any heating medium", "Remove all colour from the concentrated liquid", "Increase the boiling point of the solution"], "correct_index": 0, "explanation": "In multiple-effect evaporation, vapour produced in the first effect heats the second, and so on, greatly reducing total steam consumption per kilogram of water removed.", "difficulty": "hard", "tags": ["evaporation", "multiple effect"]})
q.append({"unit_id": "pharm-i-unit-4", "question_text": "Evaporation under reduced pressure is preferred for solutions that:", "options": ["Contain heat-sensitive substances decomposing at high temperature", "Contain only inorganic salts stable to heat", "Must be evaporated at boiling point under normal pressure", "Are highly viscous and cold"], "correct_index": 0, "explanation": "Applying a vacuum lowers the boiling point so the solvent evaporates at a lower temperature, protecting thermolabile active constituents.", "difficulty": "medium", "tags": ["evaporation", "vacuum"]})
q.append({"unit_id": "pharm-i-unit-4", "question_text": "In a rising (climbing) film evaporator, the liquid rises up the heated tubes because:", "options": ["Vapour bubbles formed at the bottom lift the liquid as a thin film", "A mechanical pump forces liquid upward only", "The tubes are coated with a waxy lubricant", "Capillary action alone draws the liquid up"], "correct_index": 0, "explanation": "As liquid boils in the tubes, expanding vapour pushes slugs of liquid upward, creating a thin climbing film with a large evaporating surface.", "difficulty": "hard", "tags": ["evaporation", "film evaporator"]})
q.append({"unit_id": "pharm-i-unit-4", "question_text": "The chief advantage of film-type evaporators over pan evaporators is:", "options": ["Short contact time of the liquid with the heating surface", "No requirement of any heat source", "Ability to handle solid crystalline masses", "Zero loss of solvent during operation"], "correct_index": 0, "explanation": "In film evaporators liquid passes over heated surfaces as a thin film very quickly, minimising thermal damage to heat-sensitive products.", "difficulty": "medium", "tags": ["evaporation", "film evaporator"]})
q.append({"unit_id": "pharm-i-unit-4", "question_text": "Steam is a widely used industrial heating medium in evaporation because it:", "options": ["Has a high latent heat and gives a uniform, controllable temperature", "Is the coldest available heating fluid", "Needs no boiler to be generated", "Cannot transfer heat through metal walls"], "correct_index": 0, "explanation": "Steam condenses at constant temperature releasing a large amount of latent heat, giving uniform heating that is easy to control by adjusting pressure.", "difficulty": "medium", "tags": ["heat transfer", "steam"]})
q.append({"unit_id": "pharm-i-unit-4", "question_text": "Lagging (insulation) applied to the outside of an evaporator vessel serves to:", "options": ["Reduce heat loss to the surroundings and protect operators", "Increase the rate of chemical reaction inside", "Make the vessel heavier for stability", "Prevent the liquid from boiling"], "correct_index": 0, "explanation": "Insulating lagging cuts heat losses from the hot surface, improving thermal efficiency and reducing the risk of burns to personnel.", "difficulty": "easy", "tags": ["heat transfer", "lagging"]})
q.append({"unit_id": "pharm-i-unit-4", "question_text": "The rate of evaporation of a liquid increases when:", "options": ["The surface area of the liquid and the temperature are increased", "The vapour pressure of the liquid is decreased", "The liquid surface is covered with an oil layer", "The surrounding air is saturated with vapour"], "correct_index": 0, "explanation": "Evaporation is faster with a larger exposed surface, higher temperature and removal of vapour, because more molecules escape from the liquid surface per unit time.", "difficulty": "easy", "tags": ["evaporation", "rate"]})
q.append({"unit_id": "pharm-i-unit-4", "question_text": "Boiling-point elevation of a solution is caused by:", "options": ["Dissolved solutes lowering the vapour pressure of the solvent", "The solvent becoming lighter on heating", "Impurities that lower the temperature of the solution", "The presence of suspended insoluble particles"], "correct_index": 0, "explanation": "Dissolved solids reduce the vapour pressure of the solvent, so a higher temperature is needed for the solution to boil, raising its boiling point.", "difficulty": "hard", "tags": ["evaporation", "boiling point"]})
q.append({"unit_id": "pharm-i-unit-4", "question_text": "A simple open evaporating pan is most suitable for:", "options": ["Small-scale evaporation of aqueous extracts and syrups", "Large-scale handling of inflammable solvents", "Evaporation of volatile essential oils", "Drying of compressed tablets"], "correct_index": 0, "explanation": "Open pans with steam jackets or direct heat are simple and cheap, suited to small batches of aqueous liquids that tolerate atmospheric boiling.", "difficulty": "medium", "tags": ["evaporation", "evaporating pan"]})
q.append({"unit_id": "pharm-i-unit-4", "question_text": "In an open pan evaporator, heat is transferred from the bottom to the bulk of the liquid mainly by:", "options": ["Convection currents set up as the heated liquid rises", "Radiation from the pan rim only", "Pure conduction through stagnant liquid", "Ultrasonic vibration of the pan"], "correct_index": 0, "explanation": "Liquid heated at the bottom becomes less dense and rises while cooler liquid descends, setting up convection currents that distribute heat through the mass.", "difficulty": "medium", "tags": ["heat transfer", "convection"]})
q.append({"unit_id": "pharm-i-unit-4", "question_text": "The function of a vacuum pump attached to a vacuum evaporator is to:", "options": ["Maintain the reduced pressure by removing vapours and non-condensable gases", "Push the concentrate back into the boiler", "Cool the heating steam before it enters the jacket", "Stir the liquid mechanically inside the pan"], "correct_index": 0, "explanation": "The vacuum pump continuously withdraws vapour and leaked air so the low pressure needed for low-temperature boiling is sustained.", "difficulty": "medium", "tags": ["evaporation", "vacuum pump"]})
q.append({"unit_id": "pharm-i-unit-4", "question_text": "Latent heat of vaporisation is the heat required to:", "options": ["Convert a liquid into vapour at its boiling point without any rise in temperature", "Raise the temperature of a liquid by one degree", "Melt a solid into liquid at the melting point", "Cool a vapour back into the liquid state"], "correct_index": 0, "explanation": "Latent heat of vaporisation is absorbed during boiling to change state from liquid to vapour while temperature remains constant.", "difficulty": "easy", "tags": ["heat transfer", "latent heat"]})
q.append({"unit_id": "pharm-i-unit-4", "question_text": "Sensible heat is the heat that causes:", "options": ["A rise in the temperature of a substance without changing its state", "A change of state at constant temperature", "Chemical decomposition of the substance", "Only radiation without any warming effect"], "correct_index": 0, "explanation": "Sensible heat warms a body and is sensed as a temperature rise; unlike latent heat it does not change the physical state.", "difficulty": "easy", "tags": ["heat transfer", "sensible heat"]})
q.append({"unit_id": "pharm-i-unit-4", "question_text": "In a forced-circulation evaporator the liquid is:", "options": ["Rapidly pumped through the heating tubes to improve heat transfer", "Allowed to remain completely stagnant over the tubes", "Circulated only by natural convection", "Evaporated without any contact with heated surfaces"], "correct_index": 0, "explanation": "A pump drives liquid at high velocity through the heating tubes, giving high heat-transfer coefficients and preventing deposition on the tube walls.", "difficulty": "hard", "tags": ["evaporation", "forced circulation"]})
q.append({"unit_id": "pharm-i-unit-4", "question_text": "The concentrated liquid left behind after evaporation of the solvent is called the:", "options": ["Concentrate or residue of the evaporation process", "Distillate collected from the condenser", "Azeotrope formed during boiling", "Entrainment carried by the vapour"], "correct_index": 0, "explanation": "Evaporation leaves the non-volatile solutes behind as a concentrate; the removed solvent vapour is condensed separately only if it is to be recovered.", "difficulty": "easy", "tags": ["evaporation", "terminology"]})

# ===== UNIT 5: DISTILLATION (15 new) =====
q.append({"unit_id": "pharm-i-unit-5", "question_text": "Distillation separates the components of a liquid mixture on the basis of differences in their:", "options": ["Boiling points", "Colours", "Electrical conductivities", "Crystalline shapes"], "correct_index": 0, "explanation": "Distillation vaporises the more volatile component first and condenses it separately, so separation depends on the difference in boiling points.", "difficulty": "easy", "tags": ["distillation", "principle"]})
q.append({"unit_id": "pharm-i-unit-5", "question_text": "Rectification is another term used for:", "options": ["Fractional distillation", "Simple distillation of water", "Destructive distillation of wood", "Steam distillation of volatile oils"], "correct_index": 0, "explanation": "Rectification is fractional distillation in which repeated vaporisation and condensation through a column sharpen the separation of close-boiling liquids.", "difficulty": "medium", "tags": ["distillation", "rectification"]})
q.append({"unit_id": "pharm-i-unit-5", "question_text": "Raoult's law states that the partial vapour pressure of a component in an ideal solution is:", "options": ["Proportional to its mole fraction in the liquid mixture", "Inversely proportional to the temperature of the mixture", "Equal to the total pressure of the atmosphere", "Independent of the composition of the mixture"], "correct_index": 0, "explanation": "According to Raoult's law the partial pressure of each component equals its mole fraction times the vapour pressure of the pure component at that temperature.", "difficulty": "hard", "tags": ["distillation", "Raoult's law"]})
q.append({"unit_id": "pharm-i-unit-5", "question_text": "Steam distillation of volatile oils is based on Dalton's law of:", "options": ["Partial pressures of immiscible liquids", "Conservation of mass during boiling", "Definite proportions of elements", "Multiple proportions of gases"], "correct_index": 0, "explanation": "With immiscible liquids each exerts its own vapour pressure independently, so the mixture boils when their sum equals atmospheric pressure, below 100°C.", "difficulty": "medium", "tags": ["distillation", "steam distillation"]})
q.append({"unit_id": "pharm-i-unit-5", "question_text": "Azeotropic mixtures such as ethanol and water cannot be completely separated by ordinary fractional distillation because the azeotrope:", "options": ["Distils over at a constant composition and boiling point like a single substance", "Sublimes directly from solid to vapour", "Decomposes into carbon and hydrogen on heating", "Has an infinitely high boiling point"], "correct_index": 0, "explanation": "At the azeotropic composition the vapour has the same composition as the liquid, so the mixture distils unchanged and cannot be split by simple fractionation.", "difficulty": "medium", "tags": ["distillation", "azeotrope"]})
q.append({"unit_id": "pharm-i-unit-5", "question_text": "The packing material inside a fractionating column mainly provides:", "options": ["A large surface area for intimate contact between rising vapour and returning liquid", "Electrical heating of the vapour stream", "Mechanical stirring of the boiling liquid", "A colour indicator for the distillate"], "correct_index": 0, "explanation": "Packing (rings, saddles) offers a large wetted surface where rising vapour repeatedly condenses and re-vaporises, enriching the more volatile component.", "difficulty": "medium", "tags": ["distillation", "fractionating column"]})
q.append({"unit_id": "pharm-i-unit-5", "question_text": "Returning part of the condensed vapour (reflux) back to the fractionating column improves:", "options": ["The purity of the distillate obtained", "The colour of the residue", "The speed of destructive decomposition", "The moisture content of the product"], "correct_index": 0, "explanation": "Reflux keeps liquid flowing down the column so rising vapour contacts it repeatedly, giving purer separation of close-boiling components.", "difficulty": "medium", "tags": ["distillation", "reflux"]})
q.append({"unit_id": "pharm-i-unit-5", "question_text": "The reflux ratio is defined as the ratio of:", "options": ["Liquid returned to the column to the distillate collected", "Heat supplied to the heat lost from the still", "Vapour condensed to vapour escaping the condenser", "Residue drawn off to feed solution added"], "correct_index": 0, "explanation": "Reflux ratio compares the condensate sent back down the column with the amount withdrawn as product; higher ratios give purer but slower distillation.", "difficulty": "hard", "tags": ["distillation", "reflux ratio"]})
q.append({"unit_id": "pharm-i-unit-5", "question_text": "Purified water produced by distillation is free of:", "options": ["Dissolved solids and microorganisms", "Only colour but not dissolved salts", "Dissolved oxygen only", "Nothing, it is identical to tap water"], "correct_index": 0, "explanation": "When water is boiled and the steam condensed, non-volatile salts and microorganisms are left behind, giving purified water suitable for pharmacy.", "difficulty": "easy", "tags": ["distillation", "purified water"]})
q.append({"unit_id": "pharm-i-unit-5", "question_text": "During distillation of fermented alcohol, the first portion of the vapour condensed (the 'foreshots') is:", "options": ["Rejected because it contains low-boiling impurities such as aldehydes", "Collected as the finest pure alcohol", "Used as the main medicinal product", "Returned to the fermenter unchanged"], "correct_index": 0, "explanation": "Low-boiling aldehydes and other impurities come over first as foreshots, which distillers discard before collecting the main alcohol fraction.", "difficulty": "hard", "tags": ["distillation", "foreshots"]})
q.append({"unit_id": "pharm-i-unit-5", "question_text": "An azeotrope is a liquid mixture that:", "options": ["Boils at a constant temperature with vapour of the same composition as the liquid", "Separates into layers as soon as it is heated", "Never boils at any temperature", "Contains only a single pure component"], "correct_index": 0, "explanation": "At the azeotropic point the vapour and liquid compositions are identical, so the mixture behaves like one pure liquid with a fixed boiling point.", "difficulty": "medium", "tags": ["distillation", "azeotrope"]})
q.append({"unit_id": "pharm-i-unit-5", "question_text": "Absolute (anhydrous) alcohol cannot be made by simple distillation of rectified spirit because:", "options": ["Ethanol and water form a constant-boiling azeotrope at about 95% alcohol", "Ethanol decomposes below its boiling point", "Water cannot be vaporised at any temperature", "Rectified spirit contains no water at all"], "correct_index": 0, "explanation": "Rectified spirit is about 95% alcohol because further water removal is blocked by the ethanol-water azeotrope; anhydrous alcohol needs special dehydration methods.", "difficulty": "hard", "tags": ["distillation", "absolute alcohol"]})
q.append({"unit_id": "pharm-i-unit-5", "question_text": "Destructive distillation is a process in which:", "options": ["Organic material is heated in the absence of air and decomposes into new products", "A volatile oil is distilled with steam", "Sea water is evaporated to obtain salt", "Two miscible liquids are separated by a column"], "correct_index": 0, "explanation": "Destructive distillation heats material such as coal or wood without air, causing chemical decomposition into new substances like charcoal, tar and gases.", "difficulty": "medium", "tags": ["distillation", "destructive distillation"]})
q.append({"unit_id": "pharm-i-unit-5", "question_text": "Rectified spirit is best described as:", "options": ["A concentrated aqueous alcohol distillate containing about 90% alcohol", "Pure alcohol free of all water", "A dilute beer containing 5% alcohol", "An alcoholic extract of a medicinal plant"], "correct_index": 0, "explanation": "Rectified spirit is the concentrated distillate from fermented wash, around 90% alcohol by volume, further purified from the weaker first fermentation product.", "difficulty": "medium", "tags": ["distillation", "rectified spirit"]})
q.append({"unit_id": "pharm-i-unit-5", "question_text": "A water-cooled condenser is more efficient than an air-cooled condenser because water:", "options": ["Absorbs and carries away the latent heat of the vapour rapidly", "Cannot remove heat from the vapour at all", "Raises the temperature of the vapour further", "Mixes freely with the distillate collected"], "correct_index": 0, "explanation": "Circulating cold water has a high heat capacity and continuously removes the latent heat, condensing vapour far faster than still air around a tube.", "difficulty": "easy", "tags": ["distillation", "condenser"]})

